<?php $media=WebAdminService::media($siteId); ?>
<div class="section-heading studio-section-heading"><div><span class="website-kicker">YOUR ASSET LIBRARY</span><h2>Media library</h2><p class="muted">Original files for this website’s local workspace.</p></div><span class="badge"><?= $summary['media'] ?> files · <?= number_format($summary['bytes']/1048576,1) ?> MB</span></div>
<section class="card" id="studio-editor"><h3>Upload a file</h3><form class="studio-upload" action="<?= $studioPath ?>/media" method="post" enctype="multipart/form-data" hx-boost="false"><?= csrf_field() ?><label>File<input type="file" name="file" accept="image/jpeg,image/png,image/webp,image/gif,application/pdf,video/mp4" required></label><button>Upload to library</button></form><p class="footnote">JPG, PNG, WebP, GIF, PDF or MP4 · up to 5 MB each. Files are stored locally and included in workspace exports.</p></section>
<?php if(!$media): ?><section class="card studio-empty"><span class="studio-empty-icon"><?= icon('folder') ?></span><h3>A home for your images and files.</h3><p class="muted">Upload your first asset using the form above.</p></section><?php else: ?><div class="studio-media-grid"><?php foreach($media as $file): ?><article class="card studio-media-card"><?php if(str_starts_with($file['mime'],'image/')): ?><img src="<?= $studioPath ?>/media/<?= e($file['id']) ?>" alt="<?= e($file['filename']) ?>" loading="lazy"><?php else: ?><div class="studio-file-preview"><?= icon('folder') ?><span><?= $file['mime']==='application/pdf'?'PDF':'VIDEO' ?></span></div><?php endif; ?><div class="studio-media-info"><strong><?= e($file['filename']) ?></strong><small><?= number_format($file['bytes']/1024,1) ?> KB · <?= e($file['mime']) ?></small><a href="<?= $studioPath ?>/media/<?= e($file['id']) ?>" hx-boost="false" download="<?= e($file['filename']) ?>">Download original</a></div></article><?php endforeach; ?></div><p class="footnote">Latest 100 files shown. All original files are included in a workspace export.</p><?php endif; ?>
